chrome.action.onClicked.addListener((tab) => {
  chrome.scripting.executeScript({
    target: { tabId: tab.id },
    func: () => {
      // Force true top across all scroll containers
      document.documentElement.scrollTop = 0;
      document.body.scrollTop = 0;
      window.scrollTo(0, 0);

      // Handle any fixed inner scroll containers that some SPAs use
      const scrollable = document.querySelectorAll(
        '[class*="scroll"], [class*="messages"], [class*="conversation"], [class*="chat"]'
      );
      scrollable.forEach(el => {
        el.scrollTop = 0;
      });
    }
  });
});

