chrome.action.onClicked.addListener(async (tab) => {
  // Toggle the floating panel on the active tab
  await chrome.scripting.executeScript({
    target: { tabId: tab.id },
    files: ["panel.js"]
  });
  await chrome.scripting.insertCSS({
    target: { tabId: tab.id },
    files: ["panel.css"]
  });
  await chrome.scripting.executeScript({
    target: { tabId: tab.id },
    func: () => {
      if (window.__scriptKittyOpen) {
        const panel = document.getElementById('script-kitty-panel');
        if (panel) panel.remove();
        window.__scriptKittyOpen = false;
      } else {
        window.__scriptKittyInit && window.__scriptKittyInit();
      }
    }
  });
});

