@import url('https://fonts.googleapis.com/css2?family=Share+Tech+Mono&family=Orbitron:wght@400;700&display=swap');

#script-kitty-panel {
  position: fixed;
  top: 60px;
  right: 20px;
  width: 340px;
  max-height: 80vh;
  background: #0a0a0f;
  border: 1px solid #00ff9d;
  border-radius: 4px;
  box-shadow: 0 0 20px rgba(0,255,157,0.3), inset 0 0 40px rgba(0,0,0,0.8);
  font-family: 'Share Tech Mono', monospace;
  color: #00ff9d;
  z-index: 2147483647;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  resize: both;
  min-width: 280px;
  min-height: 200px;
}

#sk-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 12px;
  background: #0d0d1a;
  border-bottom: 1px solid #00ff9d;
  cursor: move;
  user-select: none;
  flex-shrink: 0;
}

#sk-title {
  font-family: 'Orbitron', monospace;
  font-size: 13px;
  font-weight: 700;
  color: #00ff9d;
  letter-spacing: 2px;
  display: flex;
  align-items: center;
  gap: 8px;
}

#sk-title::before {
  content: '🐱';
  font-size: 14px;
}

#sk-controls {
  display: flex;
  gap: 6px;
}

#sk-controls button {
  background: none;
  border: 1px solid #00ff9d44;
  color: #00ff9d;
  font-size: 10px;
  width: 20px;
  height: 20px;
  cursor: pointer;
  border-radius: 2px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.15s;
  padding: 0;
}

#sk-controls button:hover {
  background: #00ff9d22;
  border-color: #00ff9d;
}

#sk-tabs {
  display: flex;
  border-bottom: 1px solid #00ff9d33;
  flex-shrink: 0;
  overflow-x: auto;
  scrollbar-width: none;
}

#sk-tabs::-webkit-scrollbar { display: none; }

.sk-tab {
  padding: 6px 12px;
  font-size: 10px;
  letter-spacing: 1px;
  cursor: pointer;
  color: #00ff9d66;
  border-bottom: 2px solid transparent;
  white-space: nowrap;
  transition: all 0.15s;
  background: none;
  border-top: none;
  border-left: none;
  border-right: none;
  font-family: 'Share Tech Mono', monospace;
}

.sk-tab:hover { color: #00ff9d; }
.sk-tab.active {
  color: #00ff9d;
  border-bottom-color: #00ff9d;
  background: #00ff9d0a;
}

#sk-body {
  flex: 1;
  overflow-y: auto;
  padding: 8px;
  scrollbar-width: thin;
  scrollbar-color: #00ff9d33 transparent;
}

#sk-body::-webkit-scrollbar { width: 4px; }
#sk-body::-webkit-scrollbar-track { background: transparent; }
#sk-body::-webkit-scrollbar-thumb { background: #00ff9d33; border-radius: 2px; }

.sk-panel { display: none; }
.sk-panel.active { display: block; }

.sk-section-label {
  font-size: 9px;
  letter-spacing: 2px;
  color: #00ff9d55;
  margin: 8px 0 4px 0;
  text-transform: uppercase;
}

.sk-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  padding: 7px 10px;
  margin-bottom: 3px;
  background: #0d0d1a;
  border: 1px solid #00ff9d22;
  border-radius: 3px;
  color: #00ff9dcc;
  font-family: 'Share Tech Mono', monospace;
  font-size: 11px;
  cursor: pointer;
  text-align: left;
  transition: all 0.15s;
}

.sk-btn:hover {
  background: #00ff9d11;
  border-color: #00ff9d66;
  color: #00ff9d;
}

.sk-btn:active {
  background: #00ff9d22;
}

.sk-btn .sk-icon {
  font-size: 12px;
  flex-shrink: 0;
}

.sk-toast {
  position: fixed;
  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);
  background: #0a0a0f;
  border: 1px solid #00ff9d;
  color: #00ff9d;
  font-family: 'Share Tech Mono', monospace;
  font-size: 11px;
  padding: 6px 16px;
  border-radius: 3px;
  z-index: 2147483648;
  box-shadow: 0 0 10px rgba(0,255,157,0.4);
  animation: sk-toast-in 0.2s ease;
}

@keyframes sk-toast-in {
  from { opacity: 0; transform: translateX(-50%) translateY(10px); }
  to { opacity: 1; transform: translateX(-50%) translateY(0); }
}

/* Custom scripts panel */
#sk-custom-list {
  margin-bottom: 8px;
}

.sk-custom-item {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 8px;
  background: #0d0d1a;
  border: 1px solid #00ff9d22;
  border-radius: 3px;
  margin-bottom: 3px;
}

.sk-custom-item span {
  flex: 1;
  font-size: 11px;
  color: #00ff9dcc;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sk-custom-item button {
  background: none;
  border: none;
  color: #00ff9d66;
  cursor: pointer;
  font-size: 11px;
  padding: 2px 4px;
  border-radius: 2px;
  font-family: 'Share Tech Mono', monospace;
  transition: all 0.15s;
}

.sk-custom-item button:hover { color: #00ff9d; background: #00ff9d11; }

.sk-input {
  width: 100%;
  background: #0d0d1a;
  border: 1px solid #00ff9d33;
  border-radius: 3px;
  color: #00ff9d;
  font-family: 'Share Tech Mono', monospace;
  font-size: 11px;
  padding: 6px 8px;
  margin-bottom: 6px;
  box-sizing: border-box;
  outline: none;
  transition: border-color 0.15s;
}

.sk-input:focus { border-color: #00ff9d; }

.sk-textarea {
  width: 100%;
  min-height: 120px;
  background: #0d0d1a;
  border: 1px solid #00ff9d33;
  border-radius: 3px;
  color: #00ff9d;
  font-family: 'Share Tech Mono', monospace;
  font-size: 11px;
  padding: 6px 8px;
  margin-bottom: 6px;
  box-sizing: border-box;
  outline: none;
  resize: vertical;
  transition: border-color 0.15s;
}

.sk-textarea:focus { border-color: #00ff9d; }
.sk-textarea::placeholder { color: #00ff9d33; }

.sk-save-btn {
  width: 100%;
  padding: 7px;
  background: #00ff9d11;
  border: 1px solid #00ff9d66;
  border-radius: 3px;
  color: #00ff9d;
  font-family: 'Orbitron', monospace;
  font-size: 10px;
  letter-spacing: 1px;
  cursor: pointer;
  transition: all 0.15s;
}

.sk-save-btn:hover {
  background: #00ff9d22;
  border-color: #00ff9d;
}

#sk-status {
  font-size: 9px;
  color: #00ff9d44;
  padding: 4px 8px;
  border-top: 1px solid #00ff9d11;
  flex-shrink: 0;
  letter-spacing: 1px;
}

