window.__scriptKittyInit = function () {
  if (document.getElementById('script-kitty-panel')) return;
  window.__scriptKittyOpen = true;

  // ── BUILT-IN SCRIPTS ──────────────────────────────────────────────────────

  const SCRIPTS = {
    navigation: [
      {
        icon: '⬆', label: 'Scroll to True Top',
        fn: () => {
          document.documentElement.scrollTop = 0;
          document.body.scrollTop = 0;
          window.scrollTo(0, 0);
          document.querySelectorAll('[class*="scroll"],[class*="message"],[class*="conversation"],[class*="chat"],[class*="feed"]')
            .forEach(el => { el.scrollTop = 0; });
          return 'Scrolled to true top';
        }
      },
      {
        icon: '⬇', label: 'Scroll to True Bottom',
        fn: () => {
          const h = Math.max(document.body.scrollHeight, document.documentElement.scrollHeight);
          window.scrollTo(0, h);
          document.querySelectorAll('[class*="scroll"],[class*="message"],[class*="conversation"],[class*="chat"],[class*="feed"]')
            .forEach(el => { el.scrollTop = el.scrollHeight; });
          return 'Scrolled to true bottom';
        }
      },
      {
        icon: '📍', label: 'Scroll to Selection',
        fn: () => {
          const sel = window.getSelection();
          if (sel && sel.rangeCount) {
            sel.getRangeAt(0).startContainer.parentElement?.scrollIntoView({ behavior: 'smooth', block: 'center' });
            return 'Scrolled to selection';
          }
          return 'No selection found';
        }
      }
    ],
    extraction: [
      {
        icon: '📋', label: 'Copy All Visible Text',
        fn: () => {
          const text = document.body.innerText;
          navigator.clipboard.writeText(text);
          return `Copied ${text.length} characters`;
        }
      },
      {
        icon: '🔗', label: 'Copy All Links',
        fn: () => {
          const links = [...document.querySelectorAll('a[href]')]
            .map(a => a.href)
            .filter(h => h.startsWith('http'))
            .filter((v, i, a) => a.indexOf(v) === i);
          navigator.clipboard.writeText(links.join('\n'));
          return `Copied ${links.length} links`;
        }
      },
      {
        icon: '💬', label: 'Export Conversation (DOM)',
        fn: () => {
          // Try to detect conversation structure across Claude, Gemini, Copilot, Grok
          const turns = [];
          const allEls = document.querySelectorAll('*');
          const candidates = [];

          allEls.forEach(el => {
            const style = window.getComputedStyle(el);
            const text = el.innerText?.trim();
            if (!text || text.length < 5) return;
            if (el.children.length > 8) return;
            const bg = style.backgroundColor;
            const align = style.textAlign;
            const ml = parseInt(style.marginLeft) || 0;
            const mr = parseInt(style.marginRight) || 0;
            if (bg && bg !== 'rgba(0, 0, 0, 0)' && bg !== 'transparent') {
              candidates.push({ el, bg, ml, mr, text });
            }
          });

          // Group by background color to detect user vs AI
          const bgMap = {};
          candidates.forEach(c => {
            bgMap[c.bg] = (bgMap[c.bg] || 0) + 1;
          });

          const topBgs = Object.entries(bgMap).sort((a, b) => b[1] - a[1]).slice(0, 2);
          if (topBgs.length < 2) {
            // Fallback: dump all paragraph text
            const paras = [...document.querySelectorAll('p, [class*="message"], [class*="turn"], [class*="bubble"]')]
              .map(el => el.innerText?.trim())
              .filter(t => t && t.length > 5);
            const output = paras.join('\n\n---\n\n');
            const blob = new Blob([output], { type: 'text/plain' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url; a.download = 'conversation.txt'; a.click();
            return `Exported ${paras.length} paragraphs (fallback mode)`;
          }

          const [bg1, bg2] = topBgs.map(b => b[0]);
          candidates.forEach(c => {
            if (c.bg === bg1) turns.push({ speaker: 'USER', text: c.text });
            else if (c.bg === bg2) turns.push({ speaker: 'AI', text: c.text });
          });

          const output = turns.map(t => `[${t.speaker}]\n${t.text}`).join('\n\n---\n\n');
          const blob = new Blob([output], { type: 'text/plain' });
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url; a.download = 'conversation.txt'; a.click();
          return `Exported ${turns.length} turns`;
        }
      },
      {
        icon: '🖼', label: 'List All Images + Alt Text',
        fn: () => {
          const imgs = [...document.querySelectorAll('img')];
          const report = imgs.map(img =>
            `SRC: ${img.src}\nALT: ${img.alt || '(none)'}`
          ).join('\n\n');
          navigator.clipboard.writeText(report);
          return `Copied info for ${imgs.length} images`;
        }
      }
    ],
    pageinfo: [
      {
        icon: '🏷', label: 'Show Meta Tags',
        fn: () => {
          const metas = [...document.querySelectorAll('meta')]
            .map(m => `${m.name || m.property || m.httpEquiv}: ${m.content}`)
            .filter(Boolean)
            .join('\n');
          navigator.clipboard.writeText(metas);
          return `Copied ${document.querySelectorAll('meta').length} meta tags`;
        }
      },
      {
        icon: '🍪', label: 'Copy All Cookies',
        fn: () => {
          navigator.clipboard.writeText(document.cookie || '(no accessible cookies)');
          return 'Cookies copied';
        }
      },
      {
        icon: '📊', label: 'Page Performance Stats',
        fn: () => {
          const nav = performance.getEntriesByType('navigation')[0];
          if (!nav) return 'No performance data available';
          const stats = [
            `DNS: ${Math.round(nav.domainLookupEnd - nav.domainLookupStart)}ms`,
            `Connect: ${Math.round(nav.connectEnd - nav.connectStart)}ms`,
            `TTFB: ${Math.round(nav.responseStart - nav.requestStart)}ms`,
            `DOM Load: ${Math.round(nav.domContentLoadedEventEnd - nav.startTime)}ms`,
            `Full Load: ${Math.round(nav.loadEventEnd - nav.startTime)}ms`,
          ].join('\n');
          navigator.clipboard.writeText(stats);
          return stats.split('\n')[4];
        }
      },
      {
        icon: '🌐', label: 'List External Resources',
        fn: () => {
          const entries = performance.getEntriesByType('resource');
          const external = [...new Set(
            entries
              .map(e => { try { return new URL(e.name).hostname; } catch { return null; } })
              .filter(h => h && h !== location.hostname)
          )];
          navigator.clipboard.writeText(external.join('\n'));
          return `${external.length} external origins copied`;
        }
      },
      {
        icon: '⚠', label: 'Check Mixed Content',
        fn: () => {
          if (location.protocol !== 'https:') return 'Page is not HTTPS';
          const mixed = [...document.querySelectorAll('img,script,link,iframe')]
            .filter(el => (el.src || el.href || '').startsWith('http:'))
            .map(el => el.src || el.href);
          if (!mixed.length) return 'No mixed content found ✓';
          navigator.clipboard.writeText(mixed.join('\n'));
          return `${mixed.length} mixed content items copied`;
        }
      },
      {
        icon: '📝', label: 'List All Forms + Actions',
        fn: () => {
          const forms = [...document.querySelectorAll('form')];
          const report = forms.map((f, i) =>
            `Form ${i + 1}: action="${f.action}" method="${f.method}"\n` +
            [...f.querySelectorAll('input,select,textarea')]
              .map(el => `  [${el.type || el.tagName}] name="${el.name}"`)
              .join('\n')
          ).join('\n\n');
          navigator.clipboard.writeText(report || '(no forms found)');
          return `${forms.length} forms copied`;
        }
      }
    ],
    dom: [
      {
        icon: '👁', label: 'Reveal Hidden Elements',
        fn: () => {
          let count = 0;
          document.querySelectorAll('*').forEach(el => {
            const s = window.getComputedStyle(el);
            if (s.display === 'none' || s.visibility === 'hidden' || s.opacity === '0') {
              el.style.cssText += ';display:block!important;visibility:visible!important;opacity:1!important;outline:1px dashed #f00!important';
              count++;
            }
          });
          return `Revealed ${count} hidden elements`;
        }
      },
      {
        icon: '🔦', label: 'Highlight All Inputs',
        fn: () => {
          document.querySelectorAll('input,textarea,select').forEach(el => {
            el.style.outline = '2px solid #ff0080';
            el.style.backgroundColor = '#ff008011';
          });
          return 'All inputs highlighted';
        }
      },
      {
        icon: '🌙', label: 'Force Dark Mode',
        fn: () => {
          if (document.documentElement.getAttribute('data-sk-dark')) {
            document.documentElement.removeAttribute('data-sk-dark');
            const s = document.getElementById('sk-dark-style');
            if (s) s.remove();
            return 'Dark mode removed';
          }
          const style = document.createElement('style');
          style.id = 'sk-dark-style';
          style.textContent = 'html[data-sk-dark]{filter:invert(1) hue-rotate(180deg)}html[data-sk-dark] img,html[data-sk-dark] video{filter:invert(1) hue-rotate(180deg)}';
          document.head.appendChild(style);
          document.documentElement.setAttribute('data-sk-dark', '1');
          return 'Dark mode forced';
        }
      },
      {
        icon: '🧹', label: 'Strip Page Clutter',
        fn: () => {
          const selectors = 'nav,header,footer,aside,[class*="sidebar"],[class*="banner"],[class*="ad-"],[class*="-ad"],[class*="popup"],[class*="modal"],[class*="cookie"],[class*="newsletter"],[id*="sidebar"],[id*="ad"]';
          const els = document.querySelectorAll(selectors);
          els.forEach(el => el.remove());
          return `Removed ${els.length} clutter elements`;
        }
      },
      {
        icon: '📐', label: 'Show Element Dimensions',
        fn: () => {
          const handler = (e) => {
            const r = e.target.getBoundingClientRect();
            const info = `${e.target.tagName} | ${Math.round(r.width)}×${Math.round(r.height)}px | top:${Math.round(r.top)} left:${Math.round(r.left)}`;
            document.getElementById('script-kitty-panel')?.querySelector('#sk-status') &&
              (document.getElementById('script-kitty-panel').querySelector('#sk-status').textContent = info);
          };
          if (window.__skDimHandler) {
            document.removeEventListener('mouseover', window.__skDimHandler);
            window.__skDimHandler = null;
            return 'Dimension inspector off';
          }
          window.__skDimHandler = handler;
          document.addEventListener('mouseover', handler);
          return 'Hover elements to see dimensions';
        }
      },
      {
        icon: '🔤', label: 'Count Words on Page',
        fn: () => {
          const text = document.body.innerText;
          const words = text.trim().split(/\s+/).filter(Boolean).length;
          const chars = text.length;
          return `${words.toLocaleString()} words / ${chars.toLocaleString()} chars`;
        }
      }
    ]
  };

  // ── BUILD UI ───────────────────────────────────────────────────────────────

  const panel = document.createElement('div');
  panel.id = 'script-kitty-panel';

  panel.innerHTML = `
    <div id="sk-header">
      <div id="sk-title">SCRIPT KITTY</div>
      <div id="sk-controls">
        <button id="sk-minimize" title="Minimize">_</button>
        <button id="sk-close" title="Close">✕</button>
      </div>
    </div>
    <div id="sk-tabs">
      <button class="sk-tab active" data-tab="navigation">NAV</button>
      <button class="sk-tab" data-tab="extraction">EXTRACT</button>
      <button class="sk-tab" data-tab="pageinfo">PAGE INFO</button>
      <button class="sk-tab" data-tab="dom">DOM</button>
      <button class="sk-tab" data-tab="custom">CUSTOM</button>
    </div>
    <div id="sk-body">
      ${Object.entries(SCRIPTS).map(([cat, scripts]) => `
        <div class="sk-panel ${cat === 'navigation' ? 'active' : ''}" data-panel="${cat}">
          ${scripts.map(s => `
            <button class="sk-btn sk-run" data-cat="${cat}" data-idx="${scripts.indexOf(s)}">
              <span class="sk-icon">${s.icon}</span>${s.label}
            </button>
          `).join('')}
        </div>
      `).join('')}
      <div class="sk-panel" data-panel="custom">
        <div class="sk-section-label">Saved Scripts</div>
        <div id="sk-custom-list"></div>
        <div class="sk-section-label">New Script</div>
        <input class="sk-input" id="sk-script-name" placeholder="Script name..." />
        <textarea class="sk-textarea" id="sk-script-code" placeholder="// JavaScript goes here&#10;// Return a string to show as status&#10;console.log('hello from Script Kitty');"></textarea>
        <button class="sk-save-btn" id="sk-save-script">[ SAVE SCRIPT ]</button>
      </div>
    </div>
    <div id="sk-status">SCRIPT KITTY v1.0 — READY</div>
  `;

  document.body.appendChild(panel);

  // ── DRAG ──────────────────────────────────────────────────────────────────

  const header = panel.querySelector('#sk-header');
  let dragging = false, ox = 0, oy = 0;

  header.addEventListener('mousedown', e => {
    if (e.target.tagName === 'BUTTON') return;
    dragging = true;
    ox = e.clientX - panel.getBoundingClientRect().left;
    oy = e.clientY - panel.getBoundingClientRect().top;
    e.preventDefault();
  });

  document.addEventListener('mousemove', e => {
    if (!dragging) return;
    panel.style.right = 'auto';
    panel.style.left = (e.clientX - ox) + 'px';
    panel.style.top = (e.clientY - oy) + 'px';
  });

  document.addEventListener('mouseup', () => { dragging = false; });

  // ── TABS ──────────────────────────────────────────────────────────────────

  panel.querySelectorAll('.sk-tab').forEach(tab => {
    tab.addEventListener('click', () => {
      panel.querySelectorAll('.sk-tab').forEach(t => t.classList.remove('active'));
      panel.querySelectorAll('.sk-panel').forEach(p => p.classList.remove('active'));
      tab.classList.add('active');
      panel.querySelector(`[data-panel="${tab.dataset.tab}"]`).classList.add('active');
      if (tab.dataset.tab === 'custom') renderCustomScripts();
    });
  });

  // ── RUN BUILT-IN SCRIPTS ─────────────────────────────────────────────────

  panel.querySelectorAll('.sk-run').forEach(btn => {
    btn.addEventListener('click', () => {
      const cat = btn.dataset.cat;
      const idx = parseInt(btn.dataset.idx);
      try {
        const result = SCRIPTS[cat][idx].fn();
        setStatus(result || 'Done');
        toast(result || 'Done');
      } catch (e) {
        setStatus('Error: ' + e.message);
        toast('Error: ' + e.message);
      }
    });
  });

  // ── CLOSE / MINIMIZE ─────────────────────────────────────────────────────

  panel.querySelector('#sk-close').addEventListener('click', () => {
    panel.remove();
    window.__scriptKittyOpen = false;
  });

  let minimized = false;
  panel.querySelector('#sk-minimize').addEventListener('click', () => {
    minimized = !minimized;
    panel.querySelector('#sk-tabs').style.display = minimized ? 'none' : '';
    panel.querySelector('#sk-body').style.display = minimized ? 'none' : '';
    panel.querySelector('#sk-status').style.display = minimized ? 'none' : '';
  });

  // ── CUSTOM SCRIPTS ────────────────────────────────────────────────────────

  function getCustomScripts() {
    try {
      return JSON.parse(localStorage.getItem('__scriptKittyCustom') || '[]');
    } catch { return []; }
  }

  function saveCustomScripts(scripts) {
    localStorage.setItem('__scriptKittyCustom', JSON.stringify(scripts));
  }

  function renderCustomScripts() {
    const list = panel.querySelector('#sk-custom-list');
    const scripts = getCustomScripts();
    if (!scripts.length) {
      list.innerHTML = '<div style="color:#00ff9d33;font-size:11px;padding:4px 0;">No saved scripts yet.</div>';
      return;
    }
    list.innerHTML = scripts.map((s, i) => `
      <div class="sk-custom-item">
        <span title="${s.name}">${s.name}</span>
        <button data-run="${i}">▶ RUN</button>
        <button data-del="${i}">✕</button>
      </div>
    `).join('');

    list.querySelectorAll('[data-run]').forEach(btn => {
      btn.addEventListener('click', () => {
        const idx = parseInt(btn.dataset.run);
        const script = getCustomScripts()[idx];
        try {
          const fn = new Function(script.code);
          const result = fn();
          setStatus(result || `Ran: ${script.name}`);
          toast(result || `Ran: ${script.name}`);
        } catch (e) {
          setStatus('Error: ' + e.message);
          toast('Error: ' + e.message);
        }
      });
    });

    list.querySelectorAll('[data-del]').forEach(btn => {
      btn.addEventListener('click', () => {
        const idx = parseInt(btn.dataset.del);
        const scripts = getCustomScripts();
        scripts.splice(idx, 1);
        saveCustomScripts(scripts);
        renderCustomScripts();
      });
    });
  }

  panel.querySelector('#sk-save-script').addEventListener('click', () => {
    const name = panel.querySelector('#sk-script-name').value.trim();
    const code = panel.querySelector('#sk-script-code').value.trim();
    if (!name || !code) { toast('Name and code required'); return; }
    const scripts = getCustomScripts();
    scripts.push({ name, code });
    saveCustomScripts(scripts);
    panel.querySelector('#sk-script-name').value = '';
    panel.querySelector('#sk-script-code').value = '';
    renderCustomScripts();
    toast(`Saved: ${name}`);
  });

  // ── HELPERS ───────────────────────────────────────────────────────────────

  function setStatus(msg) {
    const s = panel.querySelector('#sk-status');
    if (s) s.textContent = msg;
  }

  function toast(msg) {
    const existing = document.querySelector('.sk-toast');
    if (existing) existing.remove();
    const t = document.createElement('div');
    t.className = 'sk-toast';
    t.textContent = msg;
    document.body.appendChild(t);
    setTimeout(() => t.remove(), 2500);
  }

  // Render custom scripts on load if on that tab
  renderCustomScripts();
};

// Auto-init on inject
window.__scriptKittyInit();

