chrome.action.onClicked.addListener(async (tab) => {
  // Check if panel is already open and toggle it off
  const [result] = await chrome.scripting.executeScript({
    target: { tabId: tab.id },
    func: () => !!document.getElementById('script-kitty-panel')
  });

  if (result.result) {
    // Panel is open — remove it
    await chrome.scripting.executeScript({
      target: { tabId: tab.id },
      func: () => {
        const p = document.getElementById('script-kitty-panel');
        if (p) p.remove();
        window.__scriptKittyOpen = false;
      }
    });
    return;
  }

  // Inject CSS first, then JS
  await chrome.scripting.insertCSS({
    target: { tabId: tab.id },
    files: ['panel.css']
  });

  await chrome.scripting.executeScript({
    target: { tabId: tab.id },
    files: ['panel.js']
  });
});

