      <div id="sk-title">🐱 SCRIPT KITTY</div>
      <div id="sk-controls">
        <button id="sk-minimize" title="Minimize">_</button>
        <button id="sk-close" title="Close">✕</button>
      </div>
    </div>
    <div id="sk-tabs">
      <button class="sk-tab active" data-tab="navigation">NAV</button>
      <button class="sk-tab" data-tab="extraction">EXTRACT</button>
      <button class="sk-tab" data-tab="pageinfo">INFO</button>
      <button class="sk-tab" data-tab="dom">DOM</button>
      <button class="sk-tab" data-tab="custom">CUSTOM</button>
    </div>
    <div id="sk-body">
      ${Object.entries(SCRIPTS).map(([cat, scripts]) => `
        <div class="sk-panel-tab ${cat === 'navigation' ? 'active' : ''}" data-panel="${cat}">
          ${scripts.map((s, i) => `
            <button class="sk-btn sk-run" data-cat="${cat}" data-idx="${i}">
              <span class="sk-icon">${s.icon}</span>${s.label}
            </button>
          `).join('')}
        </div>
      `).join('')}
