  const skHeader = shadow.getElementById('sk-header');
  let dragging = false, ox = 0, oy = 0;

  skHeader.addEventListener('mousedown', e => {
    if (e.target.tagName === 'BUTTON') return;
    dragging = true;
    const rect = panel.getBoundingClientRect();
    ox = e.clientX - rect.left;
    oy = e.clientY - rect.top;
    e.preventDefault();
  });

  document.addEventListener('mousemove', e => {
    if (!dragging) return;
    panel.style.right = 'auto';
    panel.style.left = (e.clientX - ox) + 'px';
    panel.style.top = (e.clientY - oy) + 'px';
  });

  document.addEventListener('mouseup', () => { dragging = false; });

  // ── TABS ──────────────────────────────────────────────────────────────────

  shadow.querySelectorAll('.sk-tab').forEach(tab => {
    tab.addEventListener('click', () => {
      shadow.querySelectorAll('.sk-tab').forEach(t => t.classList.remove('active'));
      shadow.querySelectorAll('.sk-panel-tab').forEach(p => {
        p.style.display = 'none';
        p.classList.remove('active');
      });
      tab.classList.add('active');
      const target = shadow.querySelector(`[data-panel="${tab.dataset.tab}"]`);
      if (target) { target.style.display = 'block'; target.classList.add('active'); }
