      const idx = parseInt(btn.dataset.idx);
      try {
        const result = SCRIPTS[cat][idx].fn();
        setStatus(result || 'Done');
        toast(result || 'Done');
      } catch (e) {
        setStatus('Error: ' + e.message);
        toast('Error: ' + e.message);
      }
    });
  });

