    panel.style.maxHeight = minimized ? 'none' : '80vh';
  });

  // ── CUSTOM SCRIPTS ────────────────────────────────────────────────────────

  function getCustomScripts() {
    try { return JSON.parse(localStorage.getItem('__scriptKittyCustom') || '[]'); }
    catch { return []; }
  }

  function saveCustomScripts(scripts) {
    localStorage.setItem('__scriptKittyCustom', JSON.stringify(scripts));
  }

  function renderCustomScripts() {
    const list = shadow.getElementById('sk-custom-list');
    const scripts = getCustomScripts();
    if (!scripts.length) {
      list.innerHTML = '<div class="sk-empty">No saved scripts yet.</div>';
      return;
    }
    list.innerHTML = scripts.map((s, i) => `
      <div class="sk-custom-item">
        <span title="${s.name}">${s.name}</span>
        <button data-run="${i}">▶</button>
        <button data-del="${i}">✕</button>
      </div>
    `).join('');

    list.querySelectorAll('[data-run]').forEach(btn => {
      btn.addEventListener('click', () => {
        const script = getCustomScripts()[parseInt(btn.dataset.run)];
        try {
          const result = new Function(script.code)();
          setStatus(result || `Ran: ${script.name}`);
          toast(result || `Ran: ${script.name}`);
        } catch (e) {
          setStatus('Error: ' + e.message);
          toast('Error: ' + e.message);
        }
      });
    });

    list.querySelectorAll('[data-del]').forEach(btn => {
      btn.addEventListener('click', () => {
        const scripts = getCustomScripts();
        scripts.splice(parseInt(btn.dataset.del), 1);
        saveCustomScripts(scripts);
        renderCustomScripts();
      });
    });
  }

  shadow.getElementById('sk-save-script').addEventListener('click', () => {
    const name = shadow.getElementById('sk-script-name').value.trim();
    const code = shadow.getElementById('sk-script-code').value.trim();
    if (!name || !code) { toast('Name and code required'); return; }
    const scripts = getCustomScripts();
    scripts.push({ name, code });
    saveCustomScripts(scripts);
    shadow.getElementById('sk-script-name').value = '';
    shadow.getElementById('sk-script-code').value = '';
    renderCustomScripts();
    toast(`Saved: ${name}`);
  });

  // ── HELPERS ───────────────────────────────────────────────────────────────

  function setStatus(msg) {
    const s = shadow.getElementById('sk-status');
    if (s) s.textContent = msg;
  }

  function toast(msg) {
    const existing = shadow.querySelector('.sk-toast');
    if (existing) existing.remove();
    const t = document.createElement('div');
    t.className = 'sk-toast';
    t.textContent = msg;
    shadow.appendChild(t);
    setTimeout(() => t.remove(), 2500);
  }

  renderCustomScripts();
};

// Auto-init on inject
if (typeof window.__scriptKittyInit === 'function') {
  window.__scriptKittyOpen = false;
  window.__scriptKittyInit();
}

