    position: fixed !important;
    top: 0 !important;
    left: 0 !important;
    width: 0 !important;
    height: 0 !important;
    z-index: 2147483647 !important;
    pointer-events: none !important;
  `;
  document.documentElement.appendChild(host);

  const shadow = host.attachShadow({ mode: 'open' });

  // ── INJECT STYLES INTO SHADOW ─────────────────────────────────────────────

  const style = document.createElement('style');
  style.textContent = `
    @import url('https://fonts.googleapis.com/css2?family=Share+Tech+Mono&family=Orbitron:wght@400;700&display=swap');

    * { box-sizing: border-box; margin: 0; padding: 0; }

    #sk-panel {
      position: fixed;
      top: 60px;
      right: 20px;
      width: 340px;
      max-height: 80vh;
      background: #0a0a0f;
      border: 1px solid #00ff9d;
      border-radius: 4px;
      box-shadow: 0 0 24px rgba(0,255,157,0.35), 0 0 4px rgba(0,255,157,0.1);
      font-family: 'Share Tech Mono', 'Courier New', monospace;
      color: #00ff9d;
      z-index: 2147483647;
      display: flex;
      flex-direction: column;
      overflow: hidden;
      min-width: 280px;
      min-height: 200px;
      pointer-events: all;
      resize: both;
    }

    #sk-header {
      display: flex;
      align-items: center;
      justify-content: space-between;
      padding: 8px 12px;
      background: #0d0d1a;
      border-bottom: 1px solid #00ff9d;
      cursor: move;
      user-select: none;
      flex-shrink: 0;
    }

    #sk-title {
      font-family: 'Orbitron', 'Courier New', monospace;
      font-size: 12px;
      font-weight: 700;
      color: #00ff9d;
      letter-spacing: 2px;
    }

    #sk-controls { display: flex; gap: 6px; }

    #sk-controls button {
      all: unset;
      border: 1px solid #00ff9d44;
      color: #00ff9d;
      font-size: 11px;
      width: 20px;
      height: 20px;
      cursor: pointer;
      border-radius: 2px;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: all 0.15s;
      text-align: center;
      line-height: 1;
    }

    #sk-controls button:hover { background: #00ff9d22; border-color: #00ff9d; }

    #sk-tabs {
      display: flex;
      border-bottom: 1px solid #00ff9d22;
      flex-shrink: 0;
      overflow-x: auto;
      scrollbar-width: none;
    }

    #sk-tabs::-webkit-scrollbar { display: none; }

    .sk-tab {
      all: unset;
      padding: 6px 11px;
      font-size: 10px;
      font-family: 'Share Tech Mono', monospace;
      letter-spacing: 1px;
      cursor: pointer;
      color: #00ff9d55;
      border-bottom: 2px solid transparent;
      white-space: nowrap;
      transition: all 0.15s;
    }

    .sk-tab:hover { color: #00ff9d; }
    .sk-tab.active { color: #00ff9d; border-bottom-color: #00ff9d; background: #00ff9d0a; }

    #sk-body {
      flex: 1;
      overflow-y: auto;
      padding: 8px;
      scrollbar-width: thin;
      scrollbar-color: #00ff9d33 transparent;
    }

    #sk-body::-webkit-scrollbar { width: 4px; }
    #sk-body::-webkit-scrollbar-thumb { background: #00ff9d33; border-radius: 2px; }

    .sk-panel { display: none; }
    .sk-panel.active { display: block; }

    .sk-section-label {
      font-size: 9px;
      letter-spacing: 2px;
      color: #00ff9d44;
      margin: 8px 0 4px 0;
      text-transform: uppercase;
      font-family: 'Share Tech Mono', monospace;
    }

    .sk-btn {
      all: unset;
      display: flex;
      align-items: center;
      gap: 8px;
      width: 100%;
      padding: 7px 10px;
      margin-bottom: 3px;
      background: #0d0d1a;
      border: 1px solid #00ff9d1a;
      border-radius: 3px;
      color: #00ff9dbb;
      font-family: 'Share Tech Mono', monospace;
      font-size: 11px;
      cursor: pointer;
      transition: all 0.15s;
    }

    .sk-btn:hover { background: #00ff9d11; border-color: #00ff9d55; color: #00ff9d; }
    .sk-btn:active { background: #00ff9d22; }
    .sk-icon { font-size: 12px; flex-shrink: 0; }

    .sk-custom-item {
      display: flex;
      align-items: center;
      gap: 6px;
      padding: 5px 8px;
      background: #0d0d1a;
      border: 1px solid #00ff9d1a;
      border-radius: 3px;
      margin-bottom: 3px;
    }

    .sk-custom-item span {
      flex: 1;
      font-size: 11px;
      font-family: 'Share Tech Mono', monospace;
      color: #00ff9dbb;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }

    .sk-custom-item button {
      all: unset;
      color: #00ff9d55;
      cursor: pointer;
      font-size: 11px;
      padding: 2px 6px;
      border-radius: 2px;
      font-family: 'Share Tech Mono', monospace;
      transition: all 0.15s;
    }

    .sk-custom-item button:hover { color: #00ff9d; background: #00ff9d11; }

    .sk-input {
      all: unset;
      display: block;
      width: 100%;
      background: #0d0d1a;
      border: 1px solid #00ff9d33;
      border-radius: 3px;
      color: #00ff9d;
      font-family: 'Share Tech Mono', monospace;
      font-size: 11px;
      padding: 6px 8px;
      margin-bottom: 6px;
    }

    .sk-input:focus { border-color: #00ff9d; outline: none; }

    .sk-textarea {
      all: unset;
      display: block;
      width: 100%;
      min-height: 120px;
      background: #0d0d1a;
      border: 1px solid #00ff9d33;
      border-radius: 3px;
      color: #00ff9d;
      font-family: 'Share Tech Mono', monospace;
      font-size: 11px;
      padding: 6px 8px;
      margin-bottom: 6px;
      resize: vertical;
      white-space: pre-wrap;
      overflow: auto;
    }

    .sk-textarea:focus { border-color: #00ff9d; outline: none; }

    .sk-save-btn {
      all: unset;
      display: block;
      width: 100%;
      padding: 7px;
      background: #00ff9d0a;
      border: 1px solid #00ff9d55;
      border-radius: 3px;
      color: #00ff9d;
      font-family: 'Orbitron', monospace;
      font-size: 10px;
      letter-spacing: 1px;
      cursor: pointer;
      text-align: center;
      transition: all 0.15s;
    }

    .sk-save-btn:hover { background: #00ff9d1a; border-color: #00ff9d; }

    #sk-status {
      font-size: 9px;
      font-family: 'Share Tech Mono', monospace;
      color: #00ff9d44;
      padding: 4px 8px;
      border-top: 1px solid #00ff9d11;
      flex-shrink: 0;
      letter-spacing: 1px;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }

    .sk-toast {
      position: fixed;
      bottom: 24px;
      left: 50%;
      transform: translateX(-50%);
      background: #0a0a0f;
      border: 1px solid #00ff9d;
      color: #00ff9d;
      font-family: 'Share Tech Mono', monospace;
      font-size: 11px;
      padding: 6px 16px;
      border-radius: 3px;
      z-index: 2147483648;
      box-shadow: 0 0 12px rgba(0,255,157,0.4);
      pointer-events: none;
      white-space: nowrap;
    }

    .sk-empty {
      color: #00ff9d33;
      font-size: 11px;
      font-family: 'Share Tech Mono', monospace;
      padding: 4px 0;
    }
  `;
  shadow.appendChild(style);

  // ── BUILD PANEL HTML ───────────────────────────────────────────────────────

  const panel = document.createElement('div');
  panel.id = 'sk-panel';

  panel.innerHTML = `
    <div id="sk-header">
      <div id="sk-title">🐱 SCRIPT KITTY</div>
      <div id="sk-controls">
        <button id="sk-minimize" title="Minimize">_</button>
        <button id="sk-close" title="Close">✕</button>
      </div>
    </div>
    <div id="sk-tabs">
      <button class="sk-tab active" data-tab="navigation">NAV</button>
      <button class="sk-tab" data-tab="extraction">EXTRACT</button>
      <button class="sk-tab" data-tab="pageinfo">INFO</button>
      <button class="sk-tab" data-tab="dom">DOM</button>
      <button class="sk-tab" data-tab="custom">CUSTOM</button>
    </div>
    <div id="sk-body">
      ${Object.entries(SCRIPTS).map(([cat, scripts]) => `
        <div class="sk-panel-tab ${cat === 'navigation' ? 'active' : ''}" data-panel="${cat}">
          ${scripts.map((s, i) => `
            <button class="sk-btn sk-run" data-cat="${cat}" data-idx="${i}">
              <span class="sk-icon">${s.icon}</span>${s.label}
            </button>
          `).join('')}
        </div>
      `).join('')}
      <div class="sk-panel-tab" data-panel="custom">
        <div class="sk-section-label">Saved Scripts</div>
        <div id="sk-custom-list"></div>
        <div class="sk-section-label">New Script</div>
        <input class="sk-input" id="sk-script-name" placeholder="Script name..." />
        <textarea class="sk-textarea" id="sk-script-code" placeholder="// JavaScript here\n// Return a string to show as status"></textarea>
        <button class="sk-save-btn" id="sk-save-script">[ SAVE SCRIPT ]</button>
      </div>
    </div>
    <div id="sk-status">SCRIPT KITTY v1.0 — READY</div>
  `;

  shadow.appendChild(panel);

  // Fix sk-panel-tab display
  shadow.querySelectorAll('.sk-panel-tab').forEach(p => {
    p.style.display = p.classList.contains('active') ? 'block' : 'none';
  });

  // ── DRAG ──────────────────────────────────────────────────────────────────

  const skHeader = shadow.getElementById('sk-header');
  let dragging = false, ox = 0, oy = 0;

  skHeader.addEventListener('mousedown', e => {
    if (e.target.tagName === 'BUTTON') return;
    dragging = true;
    const rect = panel.getBoundingClientRect();
    ox = e.clientX - rect.left;
    oy = e.clientY - rect.top;
    e.preventDefault();
  });

  document.addEventListener('mousemove', e => {
    if (!dragging) return;
    panel.style.right = 'auto';
    panel.style.left = (e.clientX - ox) + 'px';
    panel.style.top = (e.clientY - oy) + 'px';
  });

  document.addEventListener('mouseup', () => { dragging = false; });

  // ── TABS ──────────────────────────────────────────────────────────────────

  shadow.querySelectorAll('.sk-tab').forEach(tab => {
    tab.addEventListener('click', () => {
      shadow.querySelectorAll('.sk-tab').forEach(t => t.classList.remove('active'));
      shadow.querySelectorAll('.sk-panel-tab').forEach(p => {
        p.style.display = 'none';
        p.classList.remove('active');
      });
      tab.classList.add('active');
      const target = shadow.querySelector(`[data-panel="${tab.dataset.tab}"]`);
      if (target) { target.style.display = 'block'; target.classList.add('active'); }
      if (tab.dataset.tab === 'custom') renderCustomScripts();
    });
  });

  // ── RUN BUILT-IN SCRIPTS ──────────────────────────────────────────────────

  shadow.querySelectorAll('.sk-run').forEach(btn => {
    btn.addEventListener('click', () => {
      const cat = btn.dataset.cat;
      const idx = parseInt(btn.dataset.idx);
      try {
        const result = SCRIPTS[cat][idx].fn();
        setStatus(result || 'Done');
        toast(result || 'Done');
      } catch (e) {
        setStatus('Error: ' + e.message);
        toast('Error: ' + e.message);
      }
    });
  });

  // ── CLOSE / MINIMIZE ──────────────────────────────────────────────────────

  shadow.getElementById('sk-close').addEventListener('click', () => {
    host.remove();
    window.__scriptKittyOpen = false;
  });

  let minimized = false;
  shadow.getElementById('sk-minimize').addEventListener('click', () => {
    minimized = !minimized;
    shadow.getElementById('sk-tabs').style.display = minimized ? 'none' : '';
    shadow.getElementById('sk-body').style.display = minimized ? 'none' : '';
    shadow.getElementById('sk-status').style.display = minimized ? 'none' : '';
    panel.style.maxHeight = minimized ? 'none' : '80vh';
  });

  // ── CUSTOM SCRIPTS ────────────────────────────────────────────────────────

  function getCustomScripts() {
    try { return JSON.parse(localStorage.getItem('__scriptKittyCustom') || '[]'); }
    catch { return []; }
  }

  function saveCustomScripts(scripts) {
    localStorage.setItem('__scriptKittyCustom', JSON.stringify(scripts));
  }

  function renderCustomScripts() {
    const list = shadow.getElementById('sk-custom-list');
    const scripts = getCustomScripts();
    if (!scripts.length) {
      list.innerHTML = '<div class="sk-empty">No saved scripts yet.</div>';
      return;
    }
    list.innerHTML = scripts.map((s, i) => `
      <div class="sk-custom-item">
        <span title="${s.name}">${s.name}</span>
        <button data-run="${i}">▶</button>
        <button data-del="${i}">✕</button>
      </div>
    `).join('');

    list.querySelectorAll('[data-run]').forEach(btn => {
      btn.addEventListener('click', () => {
        const script = getCustomScripts()[parseInt(btn.dataset.run)];
        try {
          const result = new Function(script.code)();
          setStatus(result || `Ran: ${script.name}`);
          toast(result || `Ran: ${script.name}`);
        } catch (e) {
          setStatus('Error: ' + e.message);
          toast('Error: ' + e.message);
        }
      });
    });

    list.querySelectorAll('[data-del]').forEach(btn => {
      btn.addEventListener('click', () => {
        const scripts = getCustomScripts();
        scripts.splice(parseInt(btn.dataset.del), 1);
        saveCustomScripts(scripts);
        renderCustomScripts();
      });
    });
  }

  shadow.getElementById('sk-save-script').addEventListener('click', () => {
    const name = shadow.getElementById('sk-script-name').value.trim();
    const code = shadow.getElementById('sk-script-code').value.trim();
    if (!name || !code) { toast('Name and code required'); return; }
    const scripts = getCustomScripts();
    scripts.push({ name, code });
    saveCustomScripts(scripts);
    shadow.getElementById('sk-script-name').value = '';
    shadow.getElementById('sk-script-code').value = '';
    renderCustomScripts();
    toast(`Saved: ${name}`);
  });

  // ── HELPERS ───────────────────────────────────────────────────────────────

  function setStatus(msg) {
    const s = shadow.getElementById('sk-status');
    if (s) s.textContent = msg;
  }

  function toast(msg) {
    const existing = shadow.querySelector('.sk-toast');
    if (existing) existing.remove();
    const t = document.createElement('div');
    t.className = 'sk-toast';
    t.textContent = msg;
    shadow.appendChild(t);
    setTimeout(() => t.remove(), 2500);
  }

  renderCustomScripts();
};

// Auto-init on inject
if (typeof window.__scriptKittyInit === 'function') {
  window.__scriptKittyOpen = false;
  window.__scriptKittyInit();
}
