window.__scriptKittyInit = function () {
  if (document.getElementById('script-kitty-host')) return;
  window.__scriptKittyOpen = true;

  // ── BUILT-IN SCRIPTS ──────────────────────────────────────────────────────

  const SCRIPTS = {
    navigation: [
      {
        icon: '⬆', label: 'Scroll to True Top',
        fn: () => {
          document.documentElement.scrollTop = 0;
          document.body.scrollTop = 0;
          window.scrollTo(0, 0);
          document.querySelectorAll('[class*="scroll"],[class*="message"],[class*="conversation"],[class*="chat"],[class*="feed"]')
            .forEach(el => { el.scrollTop = 0; });
          return 'Scrolled to true top';
        }
      },
      {
        icon: '⬇', label: 'Scroll to True Bottom',
        fn: () => {
          const h = Math.max(document.body.scrollHeight, document.documentElement.scrollHeight);
          window.scrollTo(0, h);
          document.querySelectorAll('[class*="scroll"],[class*="message"],[class*="conversation"],[class*="chat"],[class*="feed"]')
            .forEach(el => { el.scrollTop = el.scrollHeight; });
          return 'Scrolled to true bottom';
        }
      },
      {
        icon: '📍', label: 'Scroll to Selection',
        fn: () => {
          const sel = window.getSelection();
          if (sel && sel.rangeCount) {
            sel.getRangeAt(0).startContainer.parentElement?.scrollIntoView({ behavior: 'smooth', block: 'center' });
            return 'Scrolled to selection';
          }
          return 'No selection found';
        }
      }
    ],
    extraction: [
      {
        icon: '📋', label: 'Copy All Visible Text',
        fn: () => {
          const text = document.body.innerText;
          navigator.clipboard.writeText(text);
          return `Copied ${text.length} characters`;
        }
      },
      {
        icon: '🔗', label: 'Copy All Links',
        fn: () => {
          const links = [...document.querySelectorAll('a[href]')]
            .map(a => a.href)
            .filter(h => h.startsWith('http'))
            .filter((v, i, a) => a.indexOf(v) === i);
          navigator.clipboard.writeText(links.join('\n'));
          return `Copied ${links.length} links`;
        }
      },
      {
        icon: '💬', label: 'Export Conversation (DOM)',
        fn: () => {
          const candidates = [];
          document.querySelectorAll('*').forEach(el => {
            const style = window.getComputedStyle(el);
            const text = el.innerText?.trim();
            if (!text || text.length < 5 || el.children.length > 8) return;
            const bg = style.backgroundColor;
            if (bg && bg !== 'rgba(0, 0, 0, 0)' && bg !== 'transparent') {
              candidates.push({ bg, text });
            }
          });
          const bgMap = {};
          candidates.forEach(c => { bgMap[c.bg] = (bgMap[c.bg] || 0) + 1; });
          const topBgs = Object.entries(bgMap).sort((a, b) => b[1] - a[1]).slice(0, 2);
          let output;
          if (topBgs.length < 2) {
            const paras = [...document.querySelectorAll('p,[class*="message"],[class*="turn"],[class*="bubble"]')]
              .map(el => el.innerText?.trim()).filter(t => t && t.length > 5);
            output = paras.join('\n\n---\n\n');
          } else {
            const [bg1, bg2] = topBgs.map(b => b[0]);
            const turns = candidates
              .filter(c => c.bg === bg1 || c.bg === bg2)
              .map(c => `[${c.bg === bg1 ? 'USER' : 'AI'}]\n${c.text}`);
            output = turns.join('\n\n---\n\n');
          }
          const blob = new Blob([output], { type: 'text/plain' });
          const a = document.createElement('a');
          a.href = URL.createObjectURL(blob);
          a.download = 'conversation.txt';
          a.click();
          return 'Conversation exported';
        }
      },
      {
        icon: '🖼', label: 'List All Images + Alt Text',
        fn: () => {
          const imgs = [...document.querySelectorAll('img')];
          const report = imgs.map(img => `SRC: ${img.src}\nALT: ${img.alt || '(none)'}`).join('\n\n');
          navigator.clipboard.writeText(report);
          return `Copied info for ${imgs.length} images`;
        }
      }
    ],
    pageinfo: [
      {
        icon: '🏷', label: 'Show Meta Tags',
        fn: () => {
          const metas = [...document.querySelectorAll('meta')]
            .map(m => `${m.name || m.property || m.httpEquiv}: ${m.content}`)
            .filter(Boolean).join('\n');
          navigator.clipboard.writeText(metas);
          return `Copied ${document.querySelectorAll('meta').length} meta tags`;
        }
      },
      {
        icon: '🍪', label: 'Copy All Cookies',
        fn: () => {
          navigator.clipboard.writeText(document.cookie || '(no accessible cookies)');
          return 'Cookies copied';
        }
      },
      {
        icon: '📊', label: 'Page Performance Stats',
        fn: () => {
          const nav = performance.getEntriesByType('navigation')[0];
          if (!nav) return 'No performance data available';
          const stats = [
            `DNS: ${Math.round(nav.domainLookupEnd - nav.domainLookupStart)}ms`,
            `Connect: ${Math.round(nav.connectEnd - nav.connectStart)}ms`,
            `TTFB: ${Math.round(nav.responseStart - nav.requestStart)}ms`,
            `DOM Load: ${Math.round(nav.domContentLoadedEventEnd - nav.startTime)}ms`,
            `Full Load: ${Math.round(nav.loadEventEnd - nav.startTime)}ms`,
          ].join('\n');
          navigator.clipboard.writeText(stats);
          return stats.split('\n')[4];
        }
      },
      {
        icon: '🌐', label: 'List External Resources',
        fn: () => {
          const external = [...new Set(
            performance.getEntriesByType('resource')
              .map(e => { try { return new URL(e.name).hostname; } catch { return null; } })
              .filter(h => h && h !== location.hostname)
          )];
          navigator.clipboard.writeText(external.join('\n'));
          return `${external.length} external origins copied`;
        }
      },
      {
        icon: '⚠', label: 'Check Mixed Content',
        fn: () => {
          if (location.protocol !== 'https:') return 'Page is not HTTPS';
          const mixed = [...document.querySelectorAll('img,script,link,iframe')]
            .filter(el => (el.src || el.href || '').startsWith('http:'))
            .map(el => el.src || el.href);
          if (!mixed.length) return 'No mixed content found ✓';
          navigator.clipboard.writeText(mixed.join('\n'));
          return `${mixed.length} mixed content items copied`;
        }
      },
      {
        icon: '📝', label: 'List All Forms + Actions',
        fn: () => {
          const forms = [...document.querySelectorAll('form')];
          const report = forms.map((f, i) =>
            `Form ${i + 1}: action="${f.action}" method="${f.method}"\n` +
            [...f.querySelectorAll('input,select,textarea')]
              .map(el => `  [${el.type || el.tagName}] name="${el.name}"`).join('\n')
          ).join('\n\n');
          navigator.clipboard.writeText(report || '(no forms found)');
          return `${forms.length} forms copied`;
        }
      }
    ],
    dom: [
      {
        icon: '👁', label: 'Reveal Hidden Elements',
        fn: () => {
          let count = 0;
          document.querySelectorAll('*').forEach(el => {
            const s = window.getComputedStyle(el);
            if (s.display === 'none' || s.visibility === 'hidden' || s.opacity === '0') {
              el.style.cssText += ';display:block!important;visibility:visible!important;opacity:1!important;outline:1px dashed #f00!important';
              count++;
            }
          });
          return `Revealed ${count} hidden elements`;
        }
      },
      {
        icon: '🔦', label: 'Highlight All Inputs',
        fn: () => {
          document.querySelectorAll('input,textarea,select').forEach(el => {
            el.style.outline = '2px solid #ff0080';
            el.style.backgroundColor = '#ff008011';
          });
          return 'All inputs highlighted';
        }
      },
      {
        icon: '🌙', label: 'Force Dark Mode',
        fn: () => {
          if (document.documentElement.getAttribute('data-sk-dark')) {
            document.documentElement.removeAttribute('data-sk-dark');
            document.getElementById('sk-dark-style')?.remove();
            return 'Dark mode removed';
          }
          const style = document.createElement('style');
          style.id = 'sk-dark-style';
          style.textContent = 'html[data-sk-dark]{filter:invert(1) hue-rotate(180deg)}html[data-sk-dark] img,html[data-sk-dark] video{filter:invert(1) hue-rotate(180deg)}';
          document.head.appendChild(style);
          document.documentElement.setAttribute('data-sk-dark', '1');
