    const candidates = [];
    document.querySelectorAll('*').forEach(el => {
      const style = window.getComputedStyle(el);
      const text = el.innerText?.trim();
      if (!text || text.length < 5 || el.children.length > 8) return;
      const bg = style.backgroundColor;
      if (bg && bg !== 'rgba(0, 0, 0, 0)' && bg !== 'transparent') {
        candidates.push({ bg, text });
      }
    });
    const bgMap = {};
    candidates.forEach(c => { bgMap[c.bg] = (bgMap[c.bg] || 0) + 1; });
    const topBgs = Object.entries(bgMap).sort((a, b) => b[1] - a[1]).slice(0, 2);
    let output;
    if (topBgs.length < 2) {
      const paras = [...document.querySelectorAll('p,[class*="message"],[class*="turn"],[class*="bubble"]')]
        .map(el => el.innerText?.trim()).filter(t => t && t.length > 5);
      output = paras.join('\n\n---\n\n');
