{
  icon: '💬', label: 'Export Conversation (DOM)',
  fn: () => {
    const turns = [];
    const pageWidth = document.documentElement.clientWidth;

    // Strategy 1: data-testid attributes (Claude, Gemini, some others)
    const testIdEls = document.querySelectorAll('[data-testid]');
    testIdEls.forEach(el => {
      const tid = el.getAttribute('data-testid') || '';
      const text = el.innerText?.trim();
      if (!text || text.length < 3) return;
      if (/human|user/i.test(tid)) turns.push({ speaker: 'YOU', text, top: el.getBoundingClientRect().top });
      else if (/assistant|claude|ai|bot/i.test(tid)) turns.push({ speaker: 'AI', text, top: el.getBoundingClientRect().top });
    });

    // Strategy 2: alignment-based detection (works on Claude.ai)
    if (turns.length === 0) {
      const allEls = [...document.querySelectorAll('div, article, section, p')];
      allEls.forEach(el => {
        const text = el.innerText?.trim();
        if (!text || text.length < 10) return;
        if (el.children.length > 10) return;
        const rect = el.getBoundingClientRect();
        if (rect.width < 50 || rect.height < 10) return;
        const style = window.getComputedStyle(el);
        const marginLeft = parseInt(style.marginLeft) || 0;
        const marginRight = parseInt(style.marginRight) || 0;
        const centerX = rect.left + rect.width / 2;
        // User messages are typically right-of-center, AI messages left-of-center
        if (marginRight > marginLeft + 20 || centerX > pageWidth * 0.6) {
          turns.push({ speaker: 'YOU', text, top: rect.top });
        } else if (marginLeft < 40 && centerX < pageWidth * 0.6 && rect.width > pageWidth * 0.3) {
          turns.push({ speaker: 'AI', text, top: rect.top });
        }
      });
    }

    // Strategy 3: class name heuristics
    if (turns.length === 0) {
      document.querySelectorAll('[class]').forEach(el => {
        const cls = el.className?.toString().toLowerCase() || '';
        const text = el.innerText?.trim();
        if (!text || text.length < 10) return;
        if (/human|user-message|from-user|sent/.test(cls)) turns.push({ speaker: 'YOU', text, top: el.getBoundingClientRect().top });
        else if (/assistant|ai-message|from-ai|received|response/.test(cls)) turns.push({ speaker: 'AI', text, top: el.getBoundingClientRect().top });
      });
    }

    // Fallback: just grab all substantial paragraphs
    if (turns.length === 0) {
      const paras = [...document.querySelectorAll('p,[class*="message"],[class*="turn"]')]
        .map(el => el.innerText?.trim()).filter(t => t && t.length > 10);
      const output = paras.join('\n\n---\n\n');
      const blob = new Blob([output], { type: 'text/plain' });
      const a = document.createElement('a');
      a.href = URL.createObjectURL(blob); a.download = 'conversation.txt'; a.click();
      return `Exported ${paras.length} blocks (fallback — no speaker detection)`;
    }

    // Sort by vertical position and deduplicate
    const seen = new Set();
    const unique = turns
      .sort((a, b) => a.top - b.top)
      .filter(t => { if (seen.has(t.text)) return false; seen.add(t.text); return true; });

    const output = unique.map(t => `[${t.speaker}]\n${t.text}`).join('\n\n---\n\n');
    const blob = new Blob([output], { type: 'text/plain' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob); a.download = 'conversation.txt'; a.click();
    return `Exported ${unique.length} turns (YOU: ${unique.filter(t=>t.speaker==='YOU').length} / AI: ${unique.filter(t=>t.speaker==='AI').length})`;
  }
},

