# Merge panel.js into content.js properly
# content.js will contain all the panel logic directly
# background.js sends a message, content.js handles it natively in content script context

cat > /home/claude/script_kitty/background.js << 'EOF'
chrome.action.onClicked.addListener(async (tab) => {
  // Send toggle message to content script
  // Content script is pre-loaded via manifest, so this always works
  try {
    await chrome.tabs.sendMessage(tab.id, { action: 'toggle' });
  } catch (e) {
    // Content script not ready yet on this tab, inject it manually
    await chrome.scripting.executeScript({
      target: { tabId: tab.id },
      files: ['content.js']
    });
    await chrome.tabs.sendMessage(tab.id, { action: 'toggle' });
  }
});
EOF
echo "background done"

